-- 1. Sources
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3117, 'https://iu.edu.sa/%D8%A7%D9%84%D9%85%D9%88%D9%87%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B7%D9%84%D9%88%D8%A8%D8%A9-%D9%84%D9%84%D8%B7%D9%84%D8%A7%D8%A8-%D8%A7%D9%84%D8%AF%D9%88%D9%84%D9%8A%D9%8A%D9%86-0', 'Qualifications required for international students | Islamic University of Madinah (official)', 'iu.edu.sa', 'scholarship', now(), true, true, now()), (3118, 'https://iu.edu.sa/media/%D8%B9%D9%85%D8%A7%D8%AF%D8%A9%20%D8%A7%D9%84%D9%82%D8%A8%D9%88%D9%84%20%D9%88%D8%A7%D9%84%D8%AA%D8%B3%D8%AC%D9%8A%D9%84/Undergraduate%20Admission%20Guide%20for%20Scholarship%20Students%20%201448%20AH.pdf', 'Undergraduate Admission Guide for Full and Partial Scholarship Students 1448 AH (English) | Islamic University of Madinah (official PDF)', 'iu.edu.sa', 'scholarship', now(), true, true, now());

-- 2. Scholarship 985 (UAEU Talented Students)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (985, $$Chancellor's Scholarship for Talented Students (UAEU)$$, $$United Arab Emirates University (UAEU)$$, $$United Arab Emirates$$, $$Tuition Waiver$$, 0, $$No single closing date is published. New students apply for the scholarship inside the UAEU admission application; continuing students apply after the previous semester's final results are released, within the window announced in the Academic Calendar. Apply together with your admission application.$$ , $$["Bachelor's"]$$, $$["All undergraduate colleges/majors at UAEU - the qualifying talent must be in innovation, the arts, sports or technology"]$$, NULL, NULL, false, true, $$UAEU's talent-based sibling to the Elite Students award (record 848): a tuition-fee discount of 100% or 50% for new undergraduate students whose excellence is in talent rather than only school grades. Per the fetched official page, the scholarship is "awarded to students who demonstrate exceptional talent in areas such as innovation, arts, sports, or technology", evidenced by certificates, awards, participation records or recommendations at the local or international level; applicants may be required to undergo talent-assessment tests or interviews. The page does not state how the 100% versus 50% level is assigned. Continuation is conditional: the 100% level requires a cumulative GPA of at least 3.6, the 50% level at least 2.75, plus an active commitment to participate in talent-related activities inside and outside the university (exhibitions, championships, etc.), holding no other scholarship or financial sponsorship, and completing the programme within the normal duration. The awards cover tuition fees only, for the normal programme duration, and are reviewed each semester/year; all other expenses are the student's responsibility. Exact AED amounts are programme-dependent and are not published on the scholarship page. Applications are made inside the UAEU admission application (new students) - the scholarship is not automatic. The page also describes the Children of UAEU Employees scheme (50%/25% for eligible staff children), which is out of scope here.$$ , $$Eligibility (fetched page, both the 100% and 50% levels): admitted to an undergraduate programme at UAEU; demonstrated talent in innovation, arts, sports or technology; evidence of talent through certificates, awards, participation records or recommendations at the local or international level; the applicant may be required to undergo talent-assessment tests or interviews. Students under 18 need guardian approval for the scholarship contract. Continuation: 100% level - cumulative GPA of at least 3.6; 50% level - cumulative GPA of at least 2.75; at both levels - commitment to participate in activities related to the talent domain inside and outside the university (such as exhibitions or championships), not holding another scholarship or financial sponsorship, and completing all programme requirements within the normal duration period. General UAEU scholarship rules on the same page: the discount applies to tuition fees only (accommodation, books and other expenses are the student's responsibility) and excludes repeated courses; continuation is evaluated after each semester/academic year on the CGPA and conditions; the scholarship is not applied retroactively to past semesters and no refunds are given for the pre-scholarship period; a signed scholarship contract assigns responsibilities; changing college or major cancels the existing scholarship (a new request may be submitted); an upgrade request to a higher discount percentage may be submitted when the conditions of that level are met; appeals may be filed within 30 days of the decision; the university reserves the right to amend scholarship policies and benefits at any time; the scholarship does not entitle the student to UAE residence or to sponsor family members. How to apply: request the scholarship inside the UAEU admission application as a new student (continuing students apply after the previous semester's final results, within the Academic Calendar window); upload the talent evidence and attend any talent-assessment test/interview requested; check the application status; sign the scholarship contract. Programme admission itself (including any English-proficiency requirement of the chosen college) follows UAEU's admission policy - this talent scheme, unlike the Elite Students scheme (record 848), publishes no Grade-12 percentage or IELTS threshold of its own on the fetched page.$$ , $$https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml$$, $$["International undergraduate applicants admitted to UAEU who demonstrate talent in innovation, the arts, sports or technology (evidenced at local or international level) - the fetched page frames the scheme for international students"]$$, $$Talent-based tuition discount: 100% or 50% of tuition fees (page does not publish how the level is assigned); tuition only, normal programme duration; renewable under the continuation conditions (CGPA 3.6 for the 100% level / 2.75 for the 50% level, active participation in talent activities, no other sponsorship).$$ , $$100% or 50% of tuition fees depending on the awarded level, for the normal duration of the programme, subject to the continuation conditions; excludes repeated courses and all non-tuition expenses.$$ , NULL, NULL, $$Not covered - the award applies to tuition fees only; accommodation, books and other living expenses are the student's responsibility.$$ , NULL, $$No scheme-specific English threshold is published for the Talented Students award on the fetched page (contrast the Elite Students tiers on record 848, which require IELTS 7.5/6.5 or equivalents); programme admission English requirements follow UAEU's general admission policy and college requirements - verify for the target programme.$$ , $$["UAEU admission application including the scholarship request (new students) or the semester scholarship application (continuing students)", "Evidence of talent in innovation, arts, sports or technology: certificates, awards, participation records at local or international level", "Letters of recommendation supporting the talent", "Any talent-assessment test or interview requested by the university", "School-leaving certificate and UAEU general admission documents for the target programme"]$$, $$https://www.uaeu.ac.ae/en/admission/$$, NULL, NULL, $$not_published$$, NULL, NULL, $$[{"pattern": "New students apply inside the UAEU admission application; continuing students apply after the previous semester's final results, within the period announced in the Academic Calendar - no single closing date is published."}]$$, $$annual$$, NULL, NULL, $$open$$, now(), now(), $$verified$$, 10, $$https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml$$, $$ADDED 2026-10-28 (enrichment batch 24) as the talent-based sibling of record 848 (Chancellor's Scholarship for Elite Students) from the same official UAEU undergraduate-scholarships page fetched first-hand in Pass 117 (source 3116). The page does not publish how the 100% vs 50% level is assigned, any AED amount, or any scheme-specific grades/IELTS threshold, so award_amount/min_gpa/min_ielts are NULL - nothing invented. The Children of UAEU Employees scheme (staff children) on the same page remains out of scope. Deadline NULL/not_published as on 848 (application inside admission; continuing-student windows per the Academic Calendar). Non-USD award: amount_usd_value = 0.$$ , true, 364, NULL, $$AED$$, $$year$$, $$variable$$);

-- 3. Scholarship 986 (Islamic University of Madinah)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (986, $$Islamic University of Madinah Scholarship for International Students$$, $$Islamic University of Madinah$$, $$Saudi Arabia$$, $$Full Tuition + Stipend$$, 0, $$Applications run through the Study in Saudi Arabia platform in an annual spring window - the 1448 AH cycle ran 19 April to 21 May 2026 and has closed. The next cycle's dates are announced on the platform and on iu.edu.sa; prepare the full document set (two recommendations, criminal-record clearance, medical report, certificate and transcript copies) well in advance.$$ , $$["Bachelor's"]$$, $$["Theoretical colleges (Arabic-medium, 4 years): Shariah (Islamic Law); Islamic Creed and Dawah; Noble Qur'an (requires full memorization of the Holy Qur'an plus a test); Noble Hadith; Arabic Language; Media; Law Systems; Economics", "Scientific colleges (English-medium): Engineering - Electrical, Mechanical, Civil, Industrial, Chemical (5 years); Computing and Information Systems - Computer Science, Data Science, Information Technology (5 years); Science - Physics, Chemistry, Mathematics, Financial and Actuarial Mathematics, Environmental Sciences (4 years)", "The Arabic-language institute is a preparatory placement stage for admitted students, not a separately chosen programme"]$$, NULL, NULL, false, true, $$The Islamic University of Madinah's full scholarship ("external scholarship") lets non-Saudi students living outside Saudi Arabia pursue a full-time bachelor's degree at no cost in Madinah, where international students make up about 85% of the regular student body and come from more than 140 countries. The fetched official 1448 AH admission guide (source 3118) lists the benefits: a monthly stipend (the amount is not published in the fetched guide), a two-month arrival allowance, a three-month graduation allowance for shipping books, a discounted economy-class air ticket at the end of each academic year via the nearest route, university housing and subsidized meals, plus campus services including free medical services and free transport between the campus and Al-Masjid An-Nabawi (the Prophet's Mosque). Students choose a theoretical college (taught in Arabic: Shariah, Creed and Dawah, Qur'an, Hadith, Arabic, Media, Law, Economics) or a scientific college (taught in English: five engineering programmes, three computing programmes, five science programmes). Learning Arabic at the university's institute is a preparatory placement stage for admitted students - it is not a separately chosen programme; an Arabic Language Placement Test places admitted students by proficiency. Admission is competitive and an application does not guarantee admission; applications without supporting documents are not considered; the university has no agents anywhere in the world - apply only through the Study in Saudi Arabia platform. A partial (internal) scholarship - tuition exemption only, with no stipend, housing or tickets - exists for non-Saudi legal residents of the Kingdom and is out of scope here.$$ , $$Full (external) scholarship admission requirements (1448 AH guide + qualifications page): general secondary certificate (high-school diploma) or equivalent - a science-track certificate for the scientific colleges; the certificate obtained within the last five years (the university president may exempt); the applicant must not be residing in Saudi Arabia; good conduct and character; age 17-25; not previously dismissed from another university for disciplinary reasons; no scholarship from another educational institution in Saudi Arabia; recommendations from recognized bodies, institutions or scholars in the home country (the document list requires TWO academic recommendations); medically fit (medical report confirming good health and absence of infectious diseases or disabilities, per the guide); a criminal-record (security) clearance certificate; pass the entrance examinations announced during the application period; commit to the regulations of the country and the university. Special conditions: the Faculty of the Holy Qur'an requires complete memorization of the Holy Qur'an confirmed by a test; applicants who graduated from schools inside Saudi Arabia are treated as INTERNAL scholarship applicants (General Aptitude Test + Achievement Test) even if they apply as external; scholarship students cannot transfer between faculties after admission - the admission is final. Declaration undertakings: regular attendance and satisfactory academic performance; do not remain in the Kingdom after graduation, withdrawal or expulsion; do not transfer sponsorship to any entity other than the university; return to the home country on completion of studies. How to apply: through the "Study in Saudi Arabia" platform during the announced window, following the platform instructions and selecting the Islamic University of Madinah; upload the full document set and any additional documents the portal requires; sit the announced entrance examinations and, where assigned, the Arabic Language Placement Test; monitor the registered email continuously - it is the official channel, and missing requests can void the application, including for visa procedures. The university has no offices or agents anywhere authorized to receive applications; the applicant is solely responsible for completing the process and keeping application credentials safe. Note: the fetched 1448 AH guide and qualifications page do not restate the "Muslim male" condition that appeared on the university's legacy English pages (which could not be fetched at verification) - confirm the current conditions on the Study in Saudi Arabia portal when applying.$$ , $$https://iu.edu.sa/%D8%A7%D9%84%D9%85%D9%88%D9%87%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B7%D9%84%D9%88%D8%A8%D8%A9-%D9%84%D9%84%D8%B7%D9%84%D8%A7%D8%A8-%D8%A7%D9%84%D8%AF%D9%88%D9%84%D9%8A%D9%8A%D9%86-0$$, $$["Non-Saudi students residing outside Saudi Arabia, aged 17-25 (full/external scholarship); the university's students come from 140+ countries. Partial (internal) scholarships - tuition exemption only - are for non-Saudi legal residents of the Kingdom and are out of scope here"]$$, $$Full external scholarship (guide wording): full-time undergraduate studies at no cost + monthly stipend (amount not published in the fetched guide) + two-month arrival allowance + three-month graduation allowance for shipping books + discounted economy-class air ticket at the end of each academic year (nearest route) + university housing + subsidized meals; campus services include free medical services and free transport to Al-Masjid An-Nabawi.$$ , $$Full-time bachelor's studies at no cost for external scholarship students (tuition-free), with stipend, housing and allowances on top. (Internal/partial scholarships for legal residents cover tuition exemption only.)$$ , NULL, NULL, $$University housing provided for external scholarship students (guide lists housing among the services provided), with subsidized meals; free transport between the campus and Al-Masjid An-Nabawi; free medical services.$$ , NULL, $$Instruction: theoretical colleges teach in Arabic; scientific colleges teach in English. External-scholarship applicants to the SCIENTIFIC colleges whose previous studies were not in English (and who are not from countries where English is an official/primary language) must provide an accredited English-proficiency certificate (IELTS, TOEFL or equivalent) - the guide publishes no score, so min_ielts is NULL. Arabic proficiency is assessed by the Arabic Language Placement Test (not mandatory for all applicants; the university determines eligibility); admitted students needing Arabic study at the university institute as a preparatory stage before entering a faculty.$$ , $$["Copy of the original high-school (secondary) certificate", "Copy of the academic transcript", "Copy of passport", "Copy of birth certificate or age-verification document", "Criminal-record clearance certificate", "Medical report confirming good health (absence of infectious diseases or disabilities, per the guide)", "Two academic recommendations from recognized scientific bodies, institutions or scholars in the home country (or university-approved individuals)", "Recent personal photograph", "Proof of English proficiency (scientific-college applicants)", "Any other documents required by the Study in Saudi Arabia portal"]$$, $$https://studyinsaudi.sa/en$$, NULL, NULL, $$not_published$$, NULL, NULL, $$[{"cycle": "1448 AH undergraduate intake via the Study in Saudi Arabia platform", "opens": "2026-04-19", "deadline": "2026-05-21", "status": "closed"}, {"pattern": "Annual spring application window on the Study in Saudi Arabia platform; the next cycle's dates are announced on the platform and on iu.edu.sa - prepare documents (two recommendations, criminal-record clearance, medical report, certificate/transcript copies) well ahead."}]$$, $$annual$$, NULL, NULL, $$upcoming$$, now(), now(), $$verified$$, 10, $$https://iu.edu.sa/media/%D8%B9%D9%85%D8%A7%D8%AF%D8%A9%20%D8%A7%D9%84%D9%82%D8%A8%D9%88%D9%84%20%D9%88%D8%A7%D9%84%D8%AA%D8%B3%D8%AC%D9%8A%D9%84/Undergraduate%20Admission%20Guide%20for%20Scholarship%20Students%20%201448%20AH.pdf$$, $$ADDED 2026-10-28 (enrichment batch 24) from first-hand fetched official evidence: the IUM qualifications page (source 3117 - 19 Apr-21 May 2026 window, requirements, Study in Saudi Arabia route) and the English 1448 AH Undergraduate Admission Guide for Scholarship Students (source 3118 - full vs partial scholarships, benefits WITHOUT a stipend amount, programme list, conditions, documents, undertakings). The monthly-stipend amount is not published in the fetched official texts and no English score is published, so award_amount/min_gpa/min_ielts are NULL - aggregator figures (e.g. SAR 840) deliberately not used. The legacy enweb English benefits page (site_Page/31693) failed to fetch twice; its snippet-only "Muslim male" line is flagged in the record text rather than encoded as verified. university_id NULL (no Madinah row in the universities catalogue). Deadline NULL/not_published: the 1448 window has closed and the next cycle is announced on the platform. Non-USD award: amount_usd_value = 0.$$ , true, NULL, NULL, $$SAR$$, $$variable$$, $$variable$$);

