INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at, created_at) VALUES (708, 364, 985, $$Chancellor's Scholarship for Talented Students$$, 'available', 'Talent-based tuition discount (100% or 50%)', '100% of tuition fees (top level)', true, false, $$Talent-based award (innovation, arts, sports, technology); no published Grade-12 percentage or IELTS threshold of its own - talent evidence is the entry test$$, $$International undergraduate applicants admitted to UAEU with evidenced talent (certificates, awards, participation records, recommendations - local or international level); possible talent-assessment test/interview. Continuation: CGPA >= 3.6 (100% level) / >= 2.75 (50% level), active participation in talent activities, no other sponsorship. Tuition fees only; apply inside the admission application.$$ , 'https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml', 'https://www.uaeu.ac.ae/en/admission/undergraduate-scholarships.shtml', 'verified_official_source', now(), now());

